PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_versions (version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_versions VALUES (1);
CREATE TABLE IF NOT EXISTS instruments (symbol TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watchlist (symbol TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 1, added_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS minute_bars (symbol TEXT NOT NULL, bar_start_at TEXT NOT NULL, revision INTEGER NOT NULL, fingerprint TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(symbol,bar_start_at,revision));
CREATE TABLE IF NOT EXISTS bar_decisions (symbol TEXT NOT NULL, bar_start_at TEXT NOT NULL, rule_version TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(symbol,bar_start_at,rule_version));
CREATE TABLE IF NOT EXISTS episodes (episode_id TEXT PRIMARY KEY, symbol TEXT NOT NULL, session_date TEXT NOT NULL, state TEXT NOT NULL, payload TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_episode ON episodes(symbol) WHERE state NOT IN ('EXPIRED','INVALIDATED');
CREATE TABLE IF NOT EXISTS episode_events (sequence INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT UNIQUE NOT NULL, episode_id TEXT NOT NULL REFERENCES episodes(episode_id), event_type TEXT NOT NULL, bar_start_at TEXT NOT NULL, recorded_at TEXT NOT NULL, payload TEXT NOT NULL, UNIQUE(episode_id,event_type,bar_start_at));
CREATE TABLE IF NOT EXISTS alert_outbox (alert_id TEXT PRIMARY KEY, episode_id TEXT NOT NULL REFERENCES episodes(episode_id), kind TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(episode_id,kind));
CREATE TABLE IF NOT EXISTS symbol_progress (symbol TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_health (symbol TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS settings_audit (sequence INTEGER PRIMARY KEY AUTOINCREMENT, recorded_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS counters (key TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS poll_samples (sequence INTEGER PRIMARY KEY AUTOINCREMENT, recorded_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_receipts (event_id TEXT NOT NULL, kind TEXT NOT NULL, browser_at TEXT NOT NULL, received_at TEXT NOT NULL, lag_seconds TEXT NOT NULL, PRIMARY KEY(event_id,kind));
